if (-not (Test-Path 'stitch_assets')) {
    New-Item -ItemType Directory -Path 'stitch_assets' | Out-Null
}

foreach ($item in $items) {
    $cleanTitle = $item.title -replace '[^a-zA-Z0-9_\-]','_'
    $imgPath = "stitch_assets/$cleanTitle`_$($item.id).png"
    $htmlPath = "stitch_assets/$cleanTitle`_$($item.id).html"
    Write-Host "Downloading $($item.title)..."
    curl.exe -L -s $item.img -o $imgPath
    curl.exe -L -s $item.html -o $htmlPath
}
